#!/usr/bin/env python3
"""G8 parity of two real MMD-to-glTF converters for original articulated PMX/VMD.

No Blender execution needed here; reference GLB is an exact prior public GHA
artifact generated by the genuine pinned MMD Tools Blender import.
"""
import argparse
import hashlib
import json
import math
from pathlib import Path
import struct
import sys

ROOT=Path(__file__).resolve().parents[2]
sys.path.insert(0,str(ROOT/"mmd"/"qualification"))
from verify_interchange import parse_glb
from verify_articulation import inspect_rotations

BONES=("センター","左腕","左手首")
REFERENCE_SHA256="e5aa5b2f068c83acbdefe1a204931e616a22b42d7c42d589b54249963ffec954"

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def parent_map(g):
    parent={}
    for i,node in enumerate(g.get("nodes",[])):
        for child in node.get("children",[]):
            if child in parent:
                raise ValueError("non-tree glTF node parent")
            parent[child]=i
    names={i:n.get("name","") for i,n in enumerate(g.get("nodes",[]))}
    chain={}
    for i,name in names.items():
        if name in BONES:
            chain[name]=names.get(parent.get(i),"") if i in parent else ""
    if set(chain)!=set(BONES):
        raise AssertionError("lost Japanese source labels in bone hierarchy "+str(chain))
    if chain["左腕"]!="センター" or chain["左手首"]!="左腕":
        raise AssertionError("bone parent hierarchy corrupted "+str(chain))
    # Blender and mmd2gltf supply different OUTER armature/container objects.
    # Those are not skin joints and must not alter the rig's source bone graph.
    if chain["センター"] in BONES:
        raise AssertionError("root bone unexpectedly parented to another source joint")
    chain["センター"]="<external-rig-root>"
    return chain

def weight_samples(g,blob):
    records=[]
    for mesh in g.get("meshes",[]):
        for prim in mesh["primitives"]:
            attributes=prim.get("attributes",{})
            if "WEIGHTS_0" not in attributes or "JOINTS_0" not in attributes:
                raise AssertionError("missing native skinned weight/joint channels")
            accessor=g["accessors"][attributes["WEIGHTS_0"]]
            if accessor.get("type")!="VEC4" or accessor.get("componentType")!=5126:
                raise AssertionError("unsupported glTF weight type")
            if accessor.get("sparse"):
                raise AssertionError("sparse weights require separate qualification")
            view=g["bufferViews"][accessor["bufferView"]]
            n=accessor["count"]
            stride=view.get("byteStride",16)
            off=view.get("byteOffset",0)+accessor.get("byteOffset",0)
            if stride<16 or not 8<=n<=1000:
                raise AssertionError("bad skinned vertex count/stride")
            for i in range(n):
                k=off+i*stride
                if k+16>len(blob):
                    raise AssertionError("out of bounds weight accessor")
                row=struct.unpack_from("<ffff",blob,k)
                if any(not math.isfinite(z) or z<-.01 for z in row):
                    raise AssertionError("negative or NaN/Inf skin weights")
                if abs(sum(row)-1.0)>.05:
                    raise AssertionError("non-normalized skin weights "+str(row))
                records.append(row)
    mixed=[row for row in records if len([v for v in row if v>.10])>=2]
    if len(mixed)<2:
        raise AssertionError("BDEF2 mixed weights lost during glTF conversion")
    return {"vertices":len(records),"mixed_weight_vertices":len(mixed)}

def angles_by_name(g, motion):
    result={}
    for track in motion["animated_rotation_tracks"]:
        name=g["nodes"][track["node"]].get("name")
        if name in BONES:
            result[name]=track["angle_radians"]
    if set(("左腕","左手首"))-set(result):
        raise AssertionError("arm/wrist rotational channels missing "+str(result))
    return result

def self_test():
    # Deliberate negative hierarchy: duplicate names and an incorrect parent.
    g={"nodes":[{"name":"センター","children":[2]},{"name":"左腕","children":[]},{"name":"左手首"}]}
    try:
        parent_map(g)
    except AssertionError:
        pass
    else:
        raise AssertionError("bad hierarchy unexpectedly passed")
    print("EXPECTED_REJECTION wrong_parent_hierarchy")

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument("--direct",type=Path)
    ap.add_argument("--blender",type=Path)
    ap.add_argument("--out",type=Path)
    ap.add_argument("--self-test",action="store_true")
    a=ap.parse_args()
    if a.self_test:
        self_test()
        return
    if not all((a.direct,a.blender,a.out)):
        ap.error("direct, blender and out required for qualification")
    if sha(a.blender)!=REFERENCE_SHA256:
        raise AssertionError("wrong baseline artifact hash; do not compare unrelated runs")
    direct,db=parse_glb(a.direct)
    blender,bb=parse_glb(a.blender)
    direct_motion=inspect_rotations(direct,db)
    blender_motion=inspect_rotations(blender,bb)
    dparents=parent_map(direct)
    bparents=parent_map(blender)
    if dparents!=bparents:
        raise AssertionError("cross-engine hierarchy mismatch")
    dw=weight_samples(direct,db)
    bw=weight_samples(blender,bb)
    da=angles_by_name(direct,direct_motion)
    ba=angles_by_name(blender,blender_motion)
    deviations={}
    for name in ("左腕","左手首"):
        delta=abs(da[name]-ba[name])
        deviations[name]=delta
        if delta>.20:
            raise AssertionError("rotation angle differs by >0.20 rad "+name+": "+str(delta))
    extras=direct.get("extras",{}).get("mmd",{})
    if len(extras.get("bones",[]))!=3 or extras.get("nameEn")!="SCP original 3-bone articulated ribbon":
        raise AssertionError("direct engine failed to preserve 3 original raw PMX bones in extras")
    result={
      "schema":"scp.mmd.articulation.parity.v1",
      "result":"PASS_TWO_ENGINE_THREE_BONE_ROTATION_WEIGHT_HIERARCHY_PARITY",
      "reference_run_id":40451441477,
      "reference_glb_sha256":sha(a.blender),
      "independent_glb_sha256":sha(a.direct),
      "bone_parent_graph":dparents,
      "blender_rotations_radians":ba,
      "direct_rotations_radians":da,
      "absolute_rotation_differences":deviations,
      "blender_weighted_skin":bw,
      "independent_weighted_skin":dw,
      "motion_samples":"both engines independently require 31 samples, 0..1 seconds",
      "rights":"both derived from same original synthetic articulated PMX/VMD; tool MIT/GPL licenses do not grant third-party asset rights",
      "unqualified":["exact MMD native deformation solver parity","source material shader fidelity","IK","physics","facial morphs"]
    }
    a.out.parent.mkdir(parents=True,exist_ok=True)
    a.out.write_text(json.dumps(result,indent=2,sort_keys=True)+"\n")
    print(json.dumps(result,sort_keys=True))

if __name__=="__main__":
    main()
